<?php\n\nuse App\Http\Middleware\BusinessUnitMiddleware;\nuse App\Models\User;\nuse App\Models\Company;\nuse App\Models\Section;\nuse App\Models\Permission;\nuse Illuminate\Http\Request;\nuse Illuminate\Http\Response;\n\ntest('vismass middleware allows access for vismass company code', function () {\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    \n    $request = Request::create('/test', 'GET');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $this->actingAs($user);\n    \n    $response = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'vismass');\n    \n    expect($response->getStatusCode())->toBe(200);\n    expect($request->get('business_unit'))->toBe('vismass');\n});\n\ntest('vismass middleware denies access for malibo company code', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $request = Request::create('/test', 'GET');\n    $request->headers->set('Accept', 'application/json');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $this->actingAs($user);\n    \n    $response = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'vismass');\n    \n    expect($response->getStatusCode())->toBe(403);\n    $responseData = json_decode($response->getContent(), true);\n    expect($responseData['error'])->toContain('Access denied to VISMASS operations');\n});\n\ntest('malibo middleware allows access for malibo company code', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $request = Request::create('/test', 'GET');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $this->actingAs($user);\n    \n    $response = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'malibo');\n    \n    expect($response->getStatusCode())->toBe(200);\n    expect($request->get('business_unit'))->toBe('malibo');\n});\n\ntest('malibo middleware denies access for vismass company code', function () {\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    \n    $request = Request::create('/test', 'GET');\n    $request->headers->set('Accept', 'application/json');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $this->actingAs($user);\n    \n    $response = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'malibo');\n    \n    expect($response->getStatusCode())->toBe(403);\n    $responseData = json_decode($response->getContent(), true);\n    expect($responseData['error'])->toContain('Access denied to MALIBO operations');\n});\n\ntest('middleware allows access based on main stock section', function () {\n    $company = Company::factory()->create(['company_code' => 'OTHER001']);\n    $user = User::factory()->create(['company_code' => 'OTHER001']);\n    \n    // Create main stock section for VISMASS access\n    $mainStockSection = Section::factory()->create([\n        'company_code' => 'OTHER001',\n        'is_main_stock' => true\n    ]);\n    \n    $user->sections()->attach($mainStockSection->id);\n    \n    $request = Request::create('/test', 'GET');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $this->actingAs($user);\n    \n    $response = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'vismass');\n    \n    expect($response->getStatusCode())->toBe(200);\n});\n\ntest('middleware allows access based on non-main stock section for malibo', function () {\n    $company = Company::factory()->create(['company_code' => 'OTHER001']);\n    $user = User::factory()->create(['company_code' => 'OTHER001']);\n    \n    // Create non-main stock section for MALIBO access\n    $printingSection = Section::factory()->create([\n        'company_code' => 'OTHER001',\n        'is_main_stock' => false,\n        'section_type' => 'store'\n    ]);\n    \n    $user->sections()->attach($printingSection->id);\n    \n    $request = Request::create('/test', 'GET');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $this->actingAs($user);\n    \n    $response = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'malibo');\n    \n    expect($response->getStatusCode())->toBe(200);\n});\n\ntest('middleware denies access for unauthenticated users', function () {\n    $request = Request::create('/test', 'GET');\n    $request->headers->set('Accept', 'application/json');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $response = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'vismass');\n    \n    expect($response->getStatusCode())->toBe(401);\n    $responseData = json_decode($response->getContent(), true);\n    expect($responseData['error'])->toBe('Unauthorized');\n});\n\ntest('middleware allows dual access for users with both business unit permissions', function () {\n    $company = Company::factory()->create(['company_code' => 'DUAL001']);\n    $user = User::factory()->create(['company_code' => 'DUAL001']);\n    \n    // Create both main stock and non-main stock sections\n    $mainStockSection = Section::factory()->create([\n        'company_code' => 'DUAL001',\n        'is_main_stock' => true\n    ]);\n    \n    $printingSection = Section::factory()->create([\n        'company_code' => 'DUAL001',\n        'is_main_stock' => false\n    ]);\n    \n    $user->sections()->attach([$mainStockSection->id, $printingSection->id]);\n    \n    $request = Request::create('/test', 'GET');\n    $middleware = new BusinessUnitMiddleware();\n    \n    $this->actingAs($user);\n    \n    // Test VISMASS access\n    $vismassResponse = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'vismass');\n    \n    expect($vismassResponse->getStatusCode())->toBe(200);\n    \n    // Test MALIBO access  \n    $maliboResponse = $middleware->handle($request, function ($req) {\n        return new Response('Success');\n    }, 'malibo');\n    \n    expect($maliboResponse->getStatusCode())->toBe(200);\n});